"use client";

import React, { useRef } from "react";
import { motion, useScroll, useTransform, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

export interface ScrollImageItem {
  src: string;
  alt?: string;
  aspectRatio?: string;
}

const DEFAULT_IMAGES: ScrollImageItem[] = [
  {
    src: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80",
    alt: "Mountain valley landscape",
    aspectRatio: "666 / 500",
  },
  {
    src: "https://images.unsplash.com/photo-1511497584788-87676104235f?auto=format&fit=crop&w=1200&q=80",
    alt: "Misty evergreen forest",
    aspectRatio: "667 / 500",
  },
  {
    src: "https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1200&q=80",
    alt: "Wilderness nature trail",
    aspectRatio: "375 / 500",
  },
  {
    src: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1200&q=80",
    alt: "Foggy mountain range",
    aspectRatio: "667 / 500",
  },
];

export interface ScrollImageRevealProps
  extends React.HTMLAttributes<HTMLDivElement> {
  items?: ScrollImageItem[];
  title?: string;
}

export function ScrollImageReveal({
  items = DEFAULT_IMAGES,
  title = "Curtain Reveal",
  className,
  ...props
}: ScrollImageRevealProps) {
  return (
    <div
      data-slot="scroll-image-reveal"
      className={cn("w-full overflow-visible", className)}
      {...props}
    >
      {title ? (
        <section className="flex h-36 items-center justify-center">
          <h2 className="text-3xl font-black tracking-tight text-neutral-900 dark:text-neutral-100 sm:text-5xl uppercase text-center">
            {title}
          </h2>
        </section>
      ) : null}

      <div className="flex flex-col gap-16 py-8">
        {items.map((item, index) => (
          <RevealCard key={item.src + index} item={item} />
        ))}
      </div>
    </div>
  );
}

function RevealCard({ item }: { item: ScrollImageItem }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"],
  });

  const clipInset = useTransform(
    scrollYProgress,
    [0.15, 0.45, 0.75, 1],
    [50, 0, 0, 50]
  );

  const clipPath = useTransform(
    clipInset,
    (val) => (shouldReduceMotion ? "none" : `inset(0% ${val}% 0% ${val}%)`)
  );

  const translateY = useTransform(
    scrollYProgress,
    [0.15, 0.5, 0.85],
    [10, 0, -10]
  );

  return (
    <div
      ref={containerRef}
      className="w-full max-w-3xl mx-auto px-4"
    >
      <motion.div
        style={{
          clipPath,
          aspectRatio: item.aspectRatio || "16 / 10",
        }}
        className="w-full overflow-hidden rounded-2xl bg-neutral-100 dark:bg-neutral-900 shadow-2xl will-change-[clip-path]"
      >
        <motion.div
          style={{
            y: shouldReduceMotion ? 0 : translateY,
          }}
          className="h-full w-full relative"
        >
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={item.src}
            alt={item.alt || "Reveal landscape"}
            className="h-full w-full object-cover select-none pointer-events-none"
            draggable={false}
          />
        </motion.div>
      </motion.div>
    </div>
  );
}
